1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Single source of truth for an owner's derived {@code identityKey} — the descriptive key returned
7	 * on an owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
8	 * where the telephone is reduced to E.164 through {@link OwnerTelephone#toE164} and the email
9	 * lower-cased through {@link OwnerEmail#normalize}; a missing email or household id contributes an
10	 * empty segment.
11	 *
12	 * <p>The {@code householdId} segment is the deterministic household id (see
13	 * {@link OwnerHousehold#householdId}), so two owners in the same household share that segment.
14	 * This class only derives the key the owner mapper returns.
15	 */
16	public final class OwnerIdentity {
17	
18	    private OwnerIdentity() {
19	    }
20	
21	    /**
22	     * Builds the identity key from its three raw parts: the submitted/stored telephone (normalized
23	     * to E.164 here), the email (lower-cased here) and the already-derived household id. Any part
24	     * that is {@code null} or cannot normalize contributes an empty segment.
25	     */
26	    public static String identityKey(String telephone, String email, String householdId) {
27	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
28	        String normalizedEmail = OwnerEmail.normalize(email);
29	        return (normalizedTelephone == null ? "" : normalizedTelephone) + "|"
30	                + (normalizedEmail == null ? "" : normalizedEmail) + "|"
31	                + (householdId == null ? "" : householdId);
32	    }
33	
34	    /**
35	     * The identity key of an already-stored owner, read from its persisted fields. The single
36	     * {@code Owner}-to-key definition used by the owner mapper to return the descriptive key.
37	     */
38	    public static String identityKey(Owner owner) {
39	        return identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
40	    }
41	}
