1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import jakarta.servlet.http.HttpServletRequest;
4	import net.officefloor.plugin.section.clazz.Flow;
5	
6	/**
7	 * Entry point of the {@code POST /api/owners} pipeline that makes a create idempotent on the optional
8	 * {@code Idempotency-Key} request header.
9	 *
10	 * <p>When the request carries a key that has already created an owner (see {@link
11	 * OwnerIdempotencyStore}), the {@code replay} branch is taken, carrying the originally created owner's
12	 * id to {@link RespondWithOwnerReplay}, which returns that owner with 200 — no duplicate is created.
13	 * Otherwise (no key, or a key not seen before) the {@code create} branch runs the normal create
14	 * pipeline, which later records the key via {@link RecordOwnerIdempotency}.
15	 */
16	public class CheckOwnerIdempotency {
17	
18	    @FunctionalInterface
19	    public interface CreateFlow {
20	        void flow();
21	    }
22	
23	    @FunctionalInterface
24	    public interface ReplayFlow {
25	        void flow(Integer ownerId);
26	    }
27	
28	    public void service(HttpServletRequest request, OwnerIdempotencyStore store,
29	            @Flow("create") CreateFlow createFlow, @Flow("replay") ReplayFlow replayFlow) {
30	        String idempotencyKey = IdempotencyKey.fromRequest(request);
31	        if (idempotencyKey != null) {
32	            Integer existingOwnerId = store.find(idempotencyKey);
33	            if (existingOwnerId != null) {
34	                replayFlow.flow(existingOwnerId); // key already seen: replay the original owner (200)
35	                return;
36	            }
37	        }
38	        createFlow.flow(); // new key (or none): run the normal create pipeline
39	    }
40	}
