1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that already share this
9	 * owner's first and last name, compared case-insensitively.
10	 *
11	 * <p>Runs in the {@code POST /api/owners} pipeline before {@link SaveOwner}, so the new owner is not
12	 * yet persisted and therefore not counted among its own namesakes. The value is frozen at creation
13	 * time and returned unchanged on later reads.
14	 */
15	public class CountOwnerNamesakes {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = owner.getFirstName();
19	        String lastName = owner.getLastName();
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (Boolean.TRUE.equals(existing.getDeleted())) {
23	                continue; // soft-deleted owners are ignored by the identity check
24	            }
25	            if (equalsIgnoreCase(existing.getFirstName(), firstName)
26	                    && equalsIgnoreCase(existing.getLastName(), lastName)) {
27	                count++;
28	            }
29	        }
30	        owner.setNamesakeCount(count);
31	    }
32	
33	    private static boolean equalsIgnoreCase(String a, String b) {
34	        return a == null ? b == null : a.equalsIgnoreCase(b);
35	    }
36	}
