1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Flags the owner as a <em>possible</em> (soft) duplicate of an existing owner.
10	 *
11	 * <p>Runs in the {@code POST /api/owners} pipeline after {@link FlagOwnerBulkSignup} and before
12	 * {@link SaveOwner}, so the new owner is not yet persisted and therefore not compared against
13	 * itself. A soft match is a weaker signal: an existing owner that
14	 * shares this owner's last name (case-insensitive) and postcode but carries a <em>different</em>
15	 * telephone. People who really are distinct but look alike — same family name, same postcode, new
16	 * phone — are still created, but flagged for review.
17	 *
18	 * <p>When such a match is found, {@code possibleDuplicate} is set to {@code true} and
19	 * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, so the
20	 * result is deterministic); otherwise {@code possibleDuplicate} is {@code false} and
21	 * {@code possibleDuplicateOf} stays null. A postcode is required on both sides for a match — an
22	 * owner with no postcode never soft-matches. The values are frozen at creation time and returned
23	 * unchanged on later reads.
24	 *
25	 * <p>A <em>declared</em> household member — a request that opted in with {@code sharesHousehold: true}
26	 * to join an existing household (same last name and postcode) — is never flagged: a declared member
27	 * is not a suspected duplicate. Such a request is left with {@code possibleDuplicate = false}.
28	 */
29	public class FlagOwnerPossibleDuplicate {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
32	            OwnerRepository ownerRepository) {
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            owner.setPossibleDuplicate(false);
35	            owner.setPossibleDuplicateOf(null);
36	            return;
37	        }
38	        String lastName = owner.getLastName();
39	        String postcode = owner.getPostcode();
40	        String telephone = owner.getTelephone();
41	
42	        Integer matchId = null;
43	        if (postcode != null && !postcode.isBlank()) {
44	            for (Owner existing : ownerRepository.findAll()) {
45	                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
46	                    continue;
47	                }
48	                if (Boolean.TRUE.equals(existing.getDeleted())) {
49	                    continue; // soft-deleted owners are ignored by the duplicate check
50	                }
51	                if (equalsIgnoreCase(existing.getLastName(), lastName)
52	                        && postcode.equals(existing.getPostcode())
53	                        && !equalsIgnoreCase(existing.getTelephone(), telephone)) {
54	                    if (matchId == null || existing.getId() < matchId) {
55	                        matchId = existing.getId();
56	                    }
57	                }
58	            }
59	        }
60	
61	        owner.setPossibleDuplicate(matchId != null);
62	        owner.setPossibleDuplicateOf(matchId);
63	    }
64	
65	    private static boolean equalsIgnoreCase(String a, String b) {
66	        return a == null ? b == null : a.equalsIgnoreCase(b);
67	    }
68	}
