1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Single source of truth for the owner-household identity rule. A household is keyed on
10	 * {@code (lastName, postcode)}: two owners whose normalized last names match and whose postcodes are
11	 * equal belong to the same household and therefore share the same {@link #householdId}. The id is
12	 * <em>deterministic</em> — it is computed purely from those two values, so every owner that joins a
13	 * household arrives at the same id independently, without coordinating through the database.
14	 *
15	 * <p>Used by {@link AssignOwnerHousehold} to stamp the id onto a new owner and by
16	 * {@link OwnerIdentity} to derive the household segment of an owner's identity key — so the
17	 * definition of "same household" lives here and nowhere else.
18	 */
19	final class OwnerHousehold {
20	
21	    private OwnerHousehold() {
22	    }
23	
24	    /**
25	     * Reduces a value to its comparison form: trimmed, inner runs of whitespace collapsed to a
26	     * single space, and lower-cased. A {@code null} value yields an empty string.
27	     */
28	    static String normalize(String value) {
29	        if (value == null) {
30	            return "";
31	        }
32	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
33	    }
34	
35	    /**
36	     * Derives the stable household identifier shared by every owner in the same household. Owners
37	     * whose normalized last name and postcode match produce the same value, so the id can be computed
38	     * independently for each joining owner without coordinating through the database. The value is
39	     * the first 12 upper-case hex characters of the SHA-256 of the normalized
40	     * {@code "<lastName>|<postcode>"}.
41	     *
42	     * <p>A household requires a postcode: when the postcode is {@code null} or blank the owner
43	     * belongs to no household and this returns {@code null}.
44	     */
45	    static String householdId(String lastName, String postcode) {
46	        if (postcode == null || postcode.isBlank()) {
47	            return null;
48	        }
49	        String key = normalize(lastName) + "|" + postcode.trim();
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256")
52	                    .digest(key.getBytes(StandardCharsets.UTF_8));
53	            StringBuilder sb = new StringBuilder();
54	            for (int i = 0; i < 6; i++) {
55	                sb.append(String.format("%02X", digest[i]));
56	            }
57	            return sb.toString();
58	        }
59	        catch (NoSuchAlgorithmException ex) {
60	            throw new IllegalStateException("SHA-256 not available", ex);
61	        }
62	    }
63	}
