1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import jakarta.validation.Valid;
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.model.OwnerRegion;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.validation.annotation.Validated;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Validates before {@link LoadOwner} runs, so an invalid body is a 400 even when the owner does not exist.
14	 */
15	@Validated
16	public class ValidateOwner {
17	
18	    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws OwnerFieldsInvalidException {
20	        // Postcode is optional; when present it must be valid for the city's region (an unknown
21	        // region accepts any 4-digit postcode), mirroring the create pipeline.
22	        String postcode = request.getPostcode();
23	        if (postcode != null && !OwnerRegion.isPostcodeValid(request.getCity(), postcode)) {
24	            throw new OwnerFieldsInvalidException(List.of("postcode"));
25	        }
26	        validated.set(request);
27	    }
28	}
