1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	/**
8	 * The owner-email rule for the create pipeline's {@link ValidateOwnerFields}: email is optional, but
9	 * when supplied it must be a syntactically valid address whose domain is not a known disposable
10	 * provider, and it is lower-cased before being stored so it is returned lower-cased.
11	 *
12	 * <p>Mirrors {@link OwnerTelephone}. As with telephone, only the create path validates and
13	 * normalizes programmatically; the update path ({@link ValidateOwner}) leans on the
14	 * bean-validation {@code @Email} / {@code @Size} constraints on the generated DTO instead, so this
15	 * helper is intentionally not referenced there.
16	 */
17	final class OwnerEmail {
18	
19	    /** Syntactic check: a non-empty local part, an {@code @}, and a dotted domain, no whitespace. */
20	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
21	
22	    /** Disposable email providers whose addresses are rejected. */
23	    private static final Set<String> DISPOSABLE_DOMAINS =
24	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
25	
26	    private OwnerEmail() {
27	    }
28	
29	    static boolean isValid(String value) {
30	        return value != null && EMAIL.matcher(value).matches();
31	    }
32	
33	    /**
34	     * Whether the address's domain is a known disposable provider (see {@link #DISPOSABLE_DOMAINS}).
35	     * Only meaningful for a syntactically {@link #isValid valid} address.
36	     */
37	    static boolean isDisposable(String value) {
38	        if (value == null) {
39	            return false;
40	        }
41	        int at = value.lastIndexOf('@');
42	        if (at < 0) {
43	            return false;
44	        }
45	        String domain = value.substring(at + 1).toLowerCase(Locale.ROOT);
46	        return DISPOSABLE_DOMAINS.contains(domain);
47	    }
48	
49	    static String normalize(String value) {
50	        return value == null ? null : value.toLowerCase(Locale.ROOT);
51	    }
52	}
