97	        return region != null ? region : OwnerRegion.localityOf(owner.getCity(), owner.getPostcode());
98	    }
99	
100	    @Named("timezone")
101	    default String timezone(Owner owner) {
102	        // The timezone is the IANA name for the owner's locality/region, from the fixed
103	        // region-to-timezone table; derive the region exactly as locality(owner) does.
104	        return OwnerRegion.timezoneOf(locality(owner));
105	    }
106	
107	    @Named("contactPreference")
108	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
109	        String email = owner.getEmail();
110	        return (email != null && !email.isBlank())
111	            ? OwnerDto.ContactPreferenceEnum.EMAIL
112	            : OwnerDto.ContactPreferenceEnum.PHONE;
113	    }
114	
115	    Owner toOwner(OwnerDto ownerDto);
116	
117	    @Mapping(target = "id", ignore = true)
118	    @Mapping(target = "pets", ignore = true)
119	    Owner toOwner(OwnerFieldsDto ownerDto);
120	
121	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
122	
123	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
124	
125	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
126	        OwnerPageDto ownerPageDto = new OwnerPageDto();
127	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
128	        ownerPageDto.setPage(ownerPage.getNumber());
129	        ownerPageDto.setSize(ownerPage.getSize());
130	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
131	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
132	        return ownerPageDto;
133	    }
134	}
